/* ---------------------------------------------------------
   OFFICIAL LOGO — exact asset, background removed, transparent PNG.
   Do not redraw/recolor — render as-is, no glow/shadow/3D/gradient/border.
--------------------------------------------------------- */
const LOGO_DATA_URI = "data:image/png;base64,";

function Logo({ size = 32, style }) {
  return (
    <img
      src={LOGO_DATA_URI}
      alt="DZ SMART LIFE"
      draggable={false}
      style={{ width: size, height: size, display: "block", objectFit: "contain", ...style }}
    />
  );
}

function LoadingScreen() {
  return (
    <div style={{ minHeight: "100vh", background: COLORS.bg, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ animation: "dzLogoPulse 1.4s ease-in-out infinite" }}>
        <Logo size={72} />
      </div>
    </div>
  );
}

